def solve():
	t = input()
	n = int(input())
	strings = []
	for i in range(n):
		strings.append(input())
	intervals = []
	for i in range(n):
		for j in range(len(t)):
			if t[j:j + len(strings[i])] == strings[i]:
				intervals.append((j, j + len(strings[i]), i))
	intervals.sort()
	if len(intervals) == 0:
		return -1
	(s, e, ind) = intervals[0]
	if s != 0:
		return -1
	mmax = 0
	used = []
	ec = -1
	for (s, e, ind) in intervals:
		if s <= mmax:
			if e > ec:
				(sc, ec, indc) = (s, e, ind)
		else:
			used.append((sc, ec, indc))
			mmax = ec
			(sc, ec, indc) = (s, e, ind)
	if mmax != len(t):
		for (s, e, ind) in intervals:
			if e == len(t):
				used.append((s, e, ind))
				break
	covered = [0 for _ in range(len(t))]
	for (s, e, ind) in used:
		for i in range(s, e):
			covered[i] = 1
	if sum(covered) == len(t):
		return used
	else:
		return -1
q = int(input())
sol = []
for _ in range(q):
	sol.append(solve())
for so in sol:
	if so == -1:
		print(-1)
	else:
		print(len(so))
		for (s, e, ind) in so:
			print(ind + 1, s + 1)
